@startuml

class User {
  + Name : string
}

class Subscriber extends User {
  + CardNumber : string
  + Balance : float
}

class Movie {
  + Title : string
}

class Order {
  + OrderDate : date
}

class Rental {
  + RentDate : date
  + ReturnDate : date
}

User "1" -- "*" Order : places
User "1" -- "*" Rental : performs
Subscriber "1" -- "0..1" Rental : uses
Order "*" -- "1" Movie : contains
Rental "*" -- "1" Movie : involves

@enduml

